INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-totomoni-1', 'sent-ex-totomoni-1', 'en', 'As you grow older, your body grows weaker.', 'authored'),
  ('st-ex-totomoni-2', 'sent-ex-totomoni-2', 'en', 'Along with economic development, daily life changed.', 'authored'),
  ('st-ex-totomoni-3', 'sent-ex-totomoni-3', 'en', 'I am going to Japan together with my family.', 'authored'),
  ('st-ex-totomoni-4', 'sent-ex-totomoni-4', 'en', 'Words change along with the times.', 'authored'),
  ('st-ex-nitsurete-1', 'sent-ex-nitsurete-1', 'en', 'As you grow older, your body grows weaker.', 'authored'),
  ('st-ex-nitsurete-2', 'sent-ex-nitsurete-2', 'en', 'As night came on, it grew colder.', 'authored'),
  ('st-ex-nitsurete-3', 'sent-ex-nitsurete-3', 'en', 'As time passed, the pain faded.', 'authored'),
  ('st-ex-nitsurete-4', 'sent-ex-nitsurete-4', 'en', 'As the town grew, the population rose.', 'authored'),
  ('st-ex-nishitagatte-1', 'sent-ex-nishitagatte-1', 'en', 'Please act in accordance with the rules.', 'authored'),
  ('st-ex-nishitagatte-2', 'sent-ex-nishitagatte-2', 'en', 'Please write it following the teacher''s explanation.', 'authored'),
  ('st-ex-nishitagatte-3', 'sent-ex-nishitagatte-3', 'en', 'As time went on, the wind grew stronger.', 'authored'),
  ('st-ex-nishitagatte-4', 'sent-ex-nishitagatte-4', 'en', 'As you grow older, your views change.', 'authored'),
  ('st-ex-niyotte-1', 'sent-ex-niyotte-1', 'en', 'Views differ from person to person.', 'authored'),
  ('st-ex-niyotte-2', 'sent-ex-niyotte-2', 'en', 'Many houses were destroyed by the earthquake.', 'authored'),
  ('st-ex-niyotte-3', 'sent-ex-niyotte-3', 'en', 'Prices change with the season.', 'authored'),
  ('st-ex-niyotte-4', 'sent-ex-niyotte-4', 'en', 'That book was written by a famous author.', 'authored'),
  ('st-ex-nitaishite-1', 'sent-ex-nitaishite-1', 'en', 'I behaved rudely towards the teacher.', 'authored'),
  ('st-ex-nitaishite-2', 'sent-ex-nitaishite-2', 'en', 'The teacher answered the student''s question.', 'authored'),
  ('st-ex-nitaishite-3', 'sent-ex-nitaishite-3', 'en', 'She is a teacher who is strict with her students.', 'authored'),
  ('st-ex-nitaishite-4', 'sent-ex-nitaishite-4', 'en', 'We oppose the government''s policy.', 'authored'),
  ('st-ex-nitsuite-1', 'sent-ex-nitsuite-1', 'en', 'I am studying the history of Japan.', 'authored'),
  ('st-ex-nitsuite-2', 'sent-ex-nitsuite-2', 'en', 'Let us talk that problem over.', 'authored'),
  ('st-ex-nitsuite-3', 'sent-ex-nitsuite-3', 'en', 'I know nothing about him.', 'authored'),
  ('st-ex-nitsuite-4', 'sent-ex-nitsuite-4', 'en', 'I am giving a presentation on the environment.', 'authored'),
  ('st-ex-nitotte-1', 'sent-ex-nitotte-1', 'en', 'For me, family matters most.', 'authored'),
  ('st-ex-nitotte-2', 'sent-ex-nitotte-2', 'en', 'For a student, that exam is hard.', 'authored'),
  ('st-ex-nitotte-3', 'sent-ex-nitotte-3', 'en', 'For him it is a big problem.', 'authored'),
  ('st-ex-nitotte-4', 'sent-ex-nitotte-4', 'en', 'For a child, play matters.', 'authored'),
  ('st-ex-kagiri-1', 'sent-ex-kagiri-1', 'en', 'As far as I know, he is an honest man.', 'authored'),
  ('st-ex-kagiri-2', 'sent-ex-kagiri-2', 'en', 'As long as my health holds, I will go on working.', 'authored'),
  ('st-ex-kagiri-3', 'sent-ex-kagiri-3', 'en', 'As far as I can see, there is no problem.', 'authored'),
  ('st-ex-kagiri-4', 'sent-ex-kagiri-4', 'en', 'As long as I have the time, I will help.', 'authored'),
  ('st-ex-sae-1', 'sent-ex-sae-1', 'en', 'He cannot even write his own name.', 'authored'),
  ('st-ex-sae-2', 'sent-ex-sae-2', 'en', 'If you have water you can survive.', 'authored'),
  ('st-ex-sae-3', 'sent-ex-sae-3', 'en', 'Even a child knows that.', 'authored'),
  ('st-ex-sae-4', 'sent-ex-sae-4', 'en', 'If you have the money you can buy it.', 'authored'),
  ('st-ex-koso-1', 'sent-ex-koso-1', 'en', 'This year I really am going to Japan.', 'authored'),
  ('st-ex-koso-2', 'sent-ex-koso-2', 'en', 'Now is precisely the time to start.', 'authored'),
  ('st-ex-koso-3', 'sent-ex-koso-3', 'en', 'It is effort that counts.', 'authored'),
  ('st-ex-koso-4', 'sent-ex-koso-4', 'en', 'This time I really do want to succeed.', 'authored')
